import {visualSlot} from './visual-ui.js';
import {newSession,getCardView,respond,nextCard,flipCard,dueQuestions,weakQuestions,masteredCount,intervene,finishSession} from './cards-core.js';
import {escapeHTML as esc,workedHTML} from './math-ui.js';
import {chapters,questions} from './data.js';
import {mathFamilies} from './math-reference.js';
import {feedbackReason,prerequisite,accuracy,topicMastered} from './adaptive.js';
export function createCardUI({getState,save,render,src,extraRefs,beep,open,notify=()=>{}}){
 let chapter=-1,family='',error='',showSetup=false;const current=()=>getState().cardSession;
 function start(mode='learn'){let session=newSession(getState(),{mode,chapter,family:mode==='math'?family:null});if(!session){error=mode==='due'?'Chưa có thẻ đến hạn. Hãy học kiến thức mới.':'Chưa có câu phù hợp trong chương đã chọn.';render();notify(error);return}let old=current();if(old&&!old.finished&&!confirm('Bắt đầu lượt mới sẽ thay phiên đang học. Kết quả đã lưu vẫn được giữ.'))return;getState().cardSession=session;showSetup=false;error='';save();open()}
 function visual(v,c,deep=false){let selected=['mcq','math'].includes(c.format)&&c.choice>=0?c.order[c.choice]:null;return visualSlot(v.q,{key:current().id+':'+c.token+':'+(deep?'deep':'brief'),deep,transfer:c.format==='transfer',generated:c.generated,problem:v.p,stageLabel:v.stageLabel,answerText:v.answerText,mode:c.quality>=2?'correct':c.choice===-1||c.choice===null?'unknown':'wrong',selectedText:selected!==null?v.options[selected]:c.choice!==null?String(c.choice):'',issue:c.format==='math'&&c.stage<3?v.reasons?.[selected]:['transfer','short'].includes(c.format)?null:feedbackReason(v.q,selected)})}
 const source=v=>src(v.q.ch,v.q.pages)+extraRefs(v.q.supplementary);
 function table(v){if(!v.worked)return '';let rows=v.rows||[['Đề cho',v.worked.given,'Theo đề'],['Ký hiệu',v.worked.symbols,'Theo quy ước']];return `<details class="math-data" open><summary>Dữ liệu đề cho · ký hiệu · đơn vị</summary><div class="table-wrap"><table><thead><tr><th>Ký hiệu / dữ kiện</th><th>Giá trị / ý nghĩa</th><th>Đơn vị</th></tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p><strong>Ký hiệu:</strong> ${esc(v.worked.symbols)}</p><p>${esc(v.assumptions||'Dùng đúng giả thiết ghi trong đề; byte = 8 bit, k/M theo hệ thập phân khi dùng bps. Không tự thêm thời gian xử lý hoặc chờ nếu đề không cho.')}</p></details>`}
 function help(v,c){if(!c.help)return '';let base=prerequisite(v.q,questions);return `<aside class="card-tip"><strong>Gỡ từng nút thắt</strong><p>${esc(c.supportReason||base.explain)}</p><p>Ví dụ minh họa Naruto tự tạo: ${esc(v.l.analogy)}</p><p class="muted">Phép so sánh chỉ giúp nhớ; hãy dùng thuật ngữ và cơ chế mạng trong lời giải. Thẻ này đã dùng hỗ trợ, không tính là làm đúng độc lập.</p></aside>`}
 function feedback(v,c){if(c.status!=='answered')return '';let correct=c.quality>=2,stage=c.format==='math'&&c.stage<3,selected=['math','mcq'].includes(c.format)&&c.choice>=0?c.order[c.choice]:null;let explanation=stage?`Bước ${c.stage+1}: ${v.answerText}. Cần hoàn thành các bước còn lại và tự làm bài tương tự.`:c.format==='transfer'?v.worked.substitution+'. '+v.worked.result:v.q.explain;
 return `<section class="card-feedback" role="status"><strong class="${correct?'success':'error'}">${correct?'Hoàn thành một bước luyện!':c.quality===1?'Hơi nhớ · sẽ ôn sớm.':'Chưa vững · mình sẽ hỏi lại.'}</strong><p><b>Đáp án:</b> ${esc(v.answerText)}</p><p>${esc(explanation)}</p>${!correct?`<p><b>Cách sửa:</b> ${esc(stage?('Bước '+(c.stage+1)+': '+(v.reasons?.[selected]||'Đối chiếu dữ kiện và quy tắc ở đáp án.')):c.format==='transfer'?'Chỉ có kết quả cuối nên chưa xác định duy nhất bước sai. Mở lời giải hoặc luyện lại từng bước.':feedbackReason(v.q,selected))}</p>`:''}${c.format==='recall'?'<p class="muted">Đây là tự đánh giá để xếp lịch ôn, không phải bằng chứng làm đúng độc lập.</p>':''}${!stage&&c.format!=='transfer'?`<aside class="card-tip"><small>Mẹo Naruto · minh họa tự tạo</small><p>${esc(v.l.analogy)}</p></aside>`:''}${visual(v,c)}<button class="secondary" data-card-deep aria-expanded="${c.deep}">Hiểu sâu hơn</button>${!correct&&c.format==='transfer'?'<button class="secondary" data-card-scaffold>Luyện lại từng bước</button>':''}</section>`}
 function deep(v,c){return c.deep&&c.status==='answered'?`<section class="panel card-deep"><h3>${esc(v.l.title)}</h3><p>${esc(v.l.body)}</p><aside class="analogy"><small>Minh họa Naruto tự tạo · không phải nội dung PDF</small><p>${esc(v.l.analogy)}</p></aside><div class="formula">${esc(v.l.memory)}</div>${workedHTML(v.worked)}${visual(v,c,true)}<p class="source">${esc(v.q.sourceLabel)} · ${source(v)}</p><p class="source">Lý thuyết: ${(v.l.refs||[v.l.pages]).map(p=>src(v.q.ch,p)).join(' · ')}${extraRefs(v.l.supplementary)}</p></section>`:''}
 function summary(s){let events=getState().profile?.events.filter(e=>e.runId===s.id)||[],ind=events.filter(e=>e.independent),assisted=events.filter(e=>e.support>0||e.viewedSolution),ratings=events.filter(e=>e.format==='recall');let weak=events.filter(e=>e.independent&&!e.ok);return `<section class="reading"><div class="eyebrow">Báo cáo luyện nhẫn thuật</div><h1>Thêm một bước trên hành trình.</h1><div class="score">${ind.filter(e=>e.ok).length}/${ind.length}</div><p>Câu đúng độc lập / số lần tự làm. ${assisted.length} lần dùng hỗ trợ, ${ratings.length} lần tự đánh giá được theo dõi riêng; các bước chuẩn bị không được tính là giải trọn bài.</p><p>${masteredCount(getState())} chủ đề vững qua nhiều ngày. ${s.retried.length} kiến thức được hỏi lại.</p>${s.mode==='diagnostic'?`<h2>Ước lượng đầu vào</h2><p>Chỉ 2 câu mỗi chương: kết quả sơ bộ, chưa đủ đánh giá thành thạo từng chủ đề.</p><ul>${[0,1,2,3].map(ch=>{let a=s.cards.filter(c=>c.ch===ch);return a.length?`<li>Chương ${ch+1}: ${a.filter(c=>c.quality>=2&&!c.support).length}/${a.length} · ${a.some(c=>c.quality<2)?'bắt đầu từ kiến thức nền':'có thể thử tình huống'}</li>`:''}).join('')}</ul>`:''}<p>${weak.length?'Nên củng cố câu sai trước, rồi thử lại không dùng gợi ý.':'Tiếp tục câu mới; đến lịch ôn hãy tự nhớ và thử bài biến thể.'}</p><div class="actions"><button class="primary" data-card-start="${weak.length?'wrong':'learn'}">${weak.length?'Củng cố phần yếu':'Học thêm 10 thẻ'}</button><button class="secondary" data-card-start="due">Ôn thẻ đến hạn</button><button class="secondary" data-go="progress">Xem hồ sơ kiến thức</button><button class="secondary" data-card-config>Chọn chương / bài tính</button><button class="secondary" data-go="home">Về trang chủ</button></div></section>`}
 function html(){if(showSetup)return setup();let s=current();if(!s)return setup();if(s.finished)return summary(s);let c=s.cards[s.index],v=getCardView(c),answered=c.status==='answered';return `<div class="quiz-wrap flash-wrap"><header class="quiz-header"><span>Thẻ ${s.index+1}/${s.cards.length} · ${s.baseCount} thẻ chính${s.cards.length>s.baseCount?' + củng cố':''}</span><div class="actions"><button class="secondary" data-card-config>Chọn lượt học</button><button class="secondary" data-card-pause>Lưu & tạm dừng</button></div></header><div class="progress"><i style="width:${s.index/s.cards.length*100}%"></i></div><section class="question flash-card"><div class="row"><small>Chương ${v.q.ch+1} · ${c.variant?'Hỏi lại bằng cách khác':c.format==='recall'?'Tự nhớ':c.format==='short'?'Trả lời ngắn':c.format==='transfer'?'Tự làm trọn vẹn':'Trắc nghiệm'}</small><span class="daily">${v.stageLabel||['','Nhận biết','Hiểu cơ chế','Áp dụng','Phối hợp'][v.q.level]}</span></div>${v.context?`<p class="math-context">${esc(v.context)}</p>`:''}<h2 tabindex="-1">${esc(v.prompt)}</h2>${table(v)}${help(v,c)}${c.format==='recall'?`<p class="muted">Tự nghĩ trước khi lật; đánh giá trí nhớ không tính là kết quả làm độc lập.</p>${c.status==='unanswered'?'<button class="primary" data-card-flip>Lật thẻ</button>':`<div class="recall-answer">${esc(v.answerText)}</div>${!answered?'<p>Bạn nhớ đến mức nào?</p><div class="actions"><button class="secondary" data-card-rate="0">Chưa nhớ</button><button class="secondary" data-card-rate="1">Hơi nhớ</button><button class="primary" data-card-rate="3">Đã nhớ</button></div>':''}`}`:['short','transfer'].includes(c.format)?`<form id="${c.format==='transfer'?'card-number-form':'card-short-form'}"><label>${c.format==='transfer'?'Đáp số ('+esc(v.p.unit)+')':'Câu trả lời ngắn'}<input name="${c.format==='transfer'?'cardNumber':'cardText'}" ${c.format==='transfer'?'inputmode="decimal"':''} autocomplete="off" maxlength="1000" value="${esc(c.draft)}" ${answered?'disabled':''} required></label><p class="muted tolerance">${c.format==='transfer'?v.p.grading.integer?'Số nguyên chính xác; không kèm đơn vị.':`Sai số cho phép ±${v.p.grading.absTol} ${esc(v.p.unit)}. Chấp nhận dấu phẩy hoặc chấm, không kèm đơn vị.`:'Chấp nhận cách viết tương đương đã biên soạn; không phân biệt dấu và chữ hoa. Nếu khác cách diễn đạt, đối chiếu đáp án.'}</p>${!answered?'<button class="primary" type="submit">Kiểm tra</button>':''}</form>`:`<div class="options">${c.order.map((original,i)=>`<button class="option ${answered?(original===v.correct?'correct':i===c.choice?'wrong':''):''}" data-card-choice="${i}" ${answered?'disabled':''}><span class="key">${i+1}</span>${esc(v.options[original])}</button>`).join('')}</div>`}${!answered?'<div class="actions card-assist"><button class="secondary" data-card-unknown>Chưa biết</button><button class="secondary" data-card-assist="easier">Dễ hơn</button><button class="secondary" data-card-assist="explain">Giải thích thêm</button><button class="secondary" data-card-assist="harder">Khó hơn</button></div>':''}${error?`<p class="error" role="alert">${esc(error)}</p>`:''}${feedback(v,c)}${answered?'<div class="quiz-actions"><span class="muted">Đã lưu câu trả lời</span><button class="primary" data-card-next>Thẻ tiếp</button></div>':''}</section>${deep(v,c)}<p class="muted card-shortcuts">1–4: chọn đáp án · Enter: chuyển thẻ sau khi trả lời. Phiên và bản nháp tự lưu.</p></div>`}
 function picker(){return `<label class="card-picker">Chọn vùng kiến thức<select data-card-chapter><option value="-1" ${chapter<0?'selected':''}>Tổng hợp cả 4 chương</option>${chapters.map((c,i)=>`<option value="${i}" ${chapter===i?'selected':''}>Chương ${i+1} · ${c.topic}</option>`).join('')}</select></label>`}
 function setup(){return `<div class="eyebrow">Luyện nhẫn thuật · 10 thẻ mỗi lượt</div><h1>Học bằng câu hỏi, nhớ bằng luyện tập.</h1><p class="muted">Có thể học ngay hoặc đánh giá đầu vào ngắn. Tăng hỗ trợ khi cần, chuyển sang tự giải khi đã vững.</p>${picker()}${current()&&!current().finished?'<button class="secondary" data-card-resume>Tiếp tục phiên đã lưu</button>':''}<div class="card-entry-grid"><button class="panel" data-card-start="learn"><h2>Học ngay</h2><p>Câu mới xen ôn, tăng dần độ khó.</p></button><button class="panel" data-card-start="due"><h2>Ôn thẻ đến hạn</h2><p>${dueQuestions(getState(),chapter).length} kiến thức cần ôn.</p></button><button class="panel" data-card-start="wrong"><h2>Luyện câu sai</h2><p>${weakQuestions(getState(),chapter).length} kiến thức còn yếu.</p></button><button class="panel" data-card-start="diagnostic"><h2>Đánh giá đầu vào</h2><p>2 câu mỗi chương đã chọn; có thể chọn Chưa biết.</p></button></div><section class="panel" style="margin-top:24px"><h2>Bài tính từng bước</h2><label>Dạng bài<select data-card-family><option value="">Luân phiên các dạng trong chương</option>${mathFamilies.filter(f=>chapter<0||f.ch===chapter).map(f=>`<option value="${f.id}" ${family===f.id?'selected':''}>${esc(f.name)}</option>`).join('')}</select></label><p>4 thẻ hướng dẫn, rồi tự làm bài tương tự. Dạng được chọn dùng số mới và kiểm tra bằng hàm tham chiếu.</p><button class="primary" data-card-start="math">Luyện bài tính</button></section>${error?`<p class="error" role="status">${esc(error)}</p>`:''}`}
 function resume(){showSetup=false;if(current()&&!current().finished){error='';open()}else start()}
 function submit(value){let s=current(),c=s?.cards[s.index];if(c?.format==='recall'&&value===null){flipCard(s);value=0}let result=respond(getState(),s,value);error=result.error||'';if(result.changed){save();beep(result.quality>=2)}render()}
 function next(){if(nextCard(current())){if(current().finished)finishSession(getState(),current());error='';save();render();document.querySelector('.flash-card h2')?.focus()}}
 function bind(){document.querySelectorAll('[data-card-config]').forEach(b=>b.onclick=()=>{showSetup=true;open()});document.querySelectorAll('[data-card-start]').forEach(b=>b.onclick=()=>start(b.dataset.cardStart));document.querySelectorAll('[data-card-resume]').forEach(b=>b.onclick=resume);document.querySelectorAll('[data-card-choice]').forEach(b=>b.onclick=()=>submit(+b.dataset.cardChoice));document.querySelectorAll('[data-card-rate]').forEach(b=>b.onclick=()=>submit(+b.dataset.cardRate));document.querySelectorAll('[data-card-assist]').forEach(b=>b.onclick=()=>{if(intervene(getState(),current(),b.dataset.cardAssist)){save();render()}});let b=document.querySelector('[data-card-flip]');if(b)b.onclick=()=>{if(flipCard(current())){save();render()}};b=document.querySelector('[data-card-next]');if(b)b.onclick=next;b=document.querySelector('[data-card-unknown]');if(b)b.onclick=()=>submit(['mcq','math'].includes(current().cards[current().index].format)?-1:null);b=document.querySelector('[data-card-deep]');if(b)b.onclick=()=>{let c=current().cards[current().index];c.deep=!c.deep;save();render()};b=document.querySelector('[data-card-scaffold]');if(b)b.onclick=()=>{let s=current(),c=s.cards[s.index];if(c.scaffolded)return;c.scaffolded=true;let block=[0,1,2,3].map(stage=>({...c,token:null,format:'math',stage,status:'unanswered',choice:null,quality:null,deep:false,help:true,support:1,draft:'',scaffolded:true}));s.cards.splice(s.index+1,0,...block);save();render();notify('Đã thêm 4 bước hướng dẫn sau thẻ này.')};b=document.querySelector('[data-card-pause]');if(b)b.onclick=()=>{save();document.querySelector('[data-go="home"]').click()};b=document.querySelector('[data-card-chapter]');if(b)b.onchange=e=>{chapter=+e.currentTarget.value;family='';error='';render()};b=document.querySelector('[data-card-family]');if(b)b.onchange=e=>{family=e.currentTarget.value};let f=document.querySelector('#card-number-form,#card-short-form');if(f){let input=f.querySelector('input');input.oninput=()=>{current().cards[current().index].draft=input.value.slice(0,1000);save()};f.onsubmit=e=>{e.preventDefault();current().cards[current().index].draft=input.value;submit(input.value)}}}
 function keyboard(e){let s=current();if(!s||s.finished||!document.querySelector('.flash-card')||/INPUT|SELECT|TEXTAREA/.test(e.target.tagName)||e.ctrlKey||e.metaKey||e.altKey||e.target.closest?.('a,summary'))return;let c=s.cards[s.index];if(/^[1-4]$/.test(e.key)&&['mcq','math'].includes(c.format)&&c.status!=='answered'){e.preventDefault();submit(+e.key-1)}else if(e.key==='Enter'&&c.status==='answered'){e.preventDefault();next()}}
 return {html,setup,picker,bind,keyboard,start,resume,chapter:()=>chapter};
}
